// scripts/lib/lock-sync.mjs の単体テスト (`just groups` が実行する)。
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { compatLine, lockDrift, lockDriftMessage, parseLock } from "./lib/lock-sync.mjs";

const REGISTRY = "registry+https://github.com/rust-lang/crates.io-index";
/** `[name, version, source?]` の並びから Cargo.lock の中身を作る (source を null にするとワークスペースのメンバー)。 */
const lock = (...packages) =>
  [
    "# This file is automatically @generated by Cargo.",
    "version = 4",
    ...packages.map(([name, version, source = REGISTRY]) =>
      [
        "",
        "[[package]]",
        `name = "${name}"`,
        `version = "${version}"`,
        ...(source === null ? [] : [`source = "${source}"`, 'checksum = "00"']),
        "dependencies = [",
        ' "libm",',
        "]",
      ].join("\n"),
    ),
    "",
  ].join("\n");

describe("parseLock", () => {
  it("外から来るパッケージだけを取り出す", () => {
    const text = lock(["glam", "0.33.11"], ["ugoe-core", "0.1.0", null], ["libm", "0.2.15"]);
    assert.deepEqual(parseLock(text), [
      { name: "glam", version: "0.33.11" },
      { name: "libm", version: "0.2.15" },
    ]);
  });
});

describe("compatLine", () => {
  it("semver で互換な系列", () => {
    assert.equal(compatLine("1.5.1"), "1");
    assert.equal(compatLine("0.33.11"), "0.33");
    assert.equal(compatLine("0.0.4"), "0.0.4");
    assert.equal(compatLine("2.0.0-rc.1"), "2");
  });
});

describe("lockDrift", () => {
  const root = lock(["glam", "0.33.11"], ["cc", "1.5.1"], ["libc", "0.2.189"]);

  it("同じ版ならずれは無い", () => {
    assert.deepEqual(lockDrift(root, lock(["glam", "0.33.11"], ["cc", "1.5.1"])), []);
  });

  it("互換な系列の別の版を見つける", () => {
    assert.deepEqual(
      lockDrift(root, lock(["libc", "0.2.190"], ["glam", "0.33.12"], ["cc", "1.6.0"])),
      [
        { name: "cc", version: "1.6.0", rootVersion: "1.5.1" },
        { name: "glam", version: "0.33.12", rootVersion: "0.33.11" },
        { name: "libc", version: "0.2.190", rootVersion: "0.2.189" },
      ],
    );
  });

  it("ルートに無いパッケージと互換でない系列は比べない", () => {
    // godot-rust の glam 0.32 はルートの glam 0.33 とは別のパッケージとして入る
    assert.deepEqual(
      lockDrift(
        root,
        lock(["glam", "0.32.1"], ["glam", "0.33.11"], ["libfuzzer-sys", "0.4.10"], ["cc", "2.0.0"]),
      ),
      [],
    );
  });

  it("ワークスペースのメンバーと path の依存は比べない", () => {
    assert.deepEqual(lockDrift(lock(["ugoe", "0.1.0"]), lock(["ugoe", "0.2.0", null])), []);
  });
});

describe("lockDriftMessage", () => {
  it("ずれた依存とルートの版に合わせる cargo update を出す", () => {
    const message = lockDriftMessage("fuzz/Cargo.lock", "fuzz/Cargo.toml", [
      { name: "glam", version: "0.33.12", rootVersion: "0.33.11" },
    ]);
    assert.match(message, /^error: fuzz\/Cargo\.lock の依存の版がルートの Cargo\.lock と違う$/m);
    assert.match(message, /^ {2}glam 0\.33\.12 \(ルートは 0\.33\.11\)$/m);
    assert.match(
      message,
      /^ {2}cargo update --manifest-path fuzz\/Cargo\.toml -p glam@0\.33\.12 --precise 0\.33\.11$/m,
    );
  });
});
